script:
toml = repo.read("Cargo.toml")
res = env.run(["cargo", "test"], check=False)
return {"toml": toml, "code": res.code, "stdout": res.stdout, "stderr": res.stderr}

res = env.run(["find", ".", "-type", "f", "-not", "-path", "./target/*", "-not", "-path", "./.git/*"], check=False)
search = repo.search("deadline")
return {"find": res.stdout, "search": search, "status": repo.status()}

res = env.run(["ls", "-la"], check=False)
res2 = env.run(["ls", "-la", "target"], check=False)
return {"ls": res.stdout + res.stderr, "target": res2.stdout + res2.stderr}

repo.write("src/retry.rs", "pub const RETRIES: u32 = 3;\n")
res = env.run(["cargo", "test"], check=False)
return {"file": repo.read("src/retry.rs"), "code": res.code, "stdout": res.stdout, "stderr": res.stderr}

res = env.run(["cargo", "test"], check=False)
res2 = env.run(["cargo", "test"], check=False)
return {"run2": {"code": res.code, "stdout": res.stdout}, "run3": {"code": res2.code, "stdout": res2.stdout}}
